-- Staging only: direct quarantined SQL contracts with isolated synthetic own profiles/sessions.
-- Explicit authored observations are test data, not inferred care, qualification or clinical approval.
-- No grants, DDL, HTTP sign-in, browser/layout or parallel-transaction acceptance claim.
-- The synthetic scope rolls back before evidence output; the outer transaction also rolls back.
BEGIN;
DO $test$
<<fixture>>
DECLARE
 t uuid:=gen_random_uuid();u uuid:=gen_random_uuid();s uuid:=gen_random_uuid();r uuid:=gen_random_uuid();
 other_actor uuid:=gen_random_uuid();other_session uuid:=gen_random_uuid();other_role uuid:=gen_random_uuid();
 c uuid:=gen_random_uuid();other_client uuid:=gen_random_uuid();relinked_auth uuid:=gen_random_uuid();relinked_session uuid:=gen_random_uuid();relink_checked boolean:=false;
 create_request uuid:=gen_random_uuid();correct_request uuid:=gen_random_uuid();confirm_request uuid:=gen_random_uuid();later_request uuid:=gen_random_uuid();
 first_id uuid;second_id uuid;third_id uuid;extra_id uuid;
 extra_packet jsonb;extra_receipt jsonb;lower_packet jsonb;lower_receipt jsonb;older_packet jsonb;older_receipt jsonb;foreign_packet jsonb;foreign_receipt jsonb;legacy_id uuid:=gen_random_uuid();
 claims jsonb;other_claims jsonb;entry jsonb;packet jsonb;value jsonb;bad jsonb;
 create_packet jsonb;create_receipt jsonb;correct_packet jsonb;correct_receipt jsonb;confirm_packet jsonb;later_packet jsonb;later_receipt jsonb;
 native_first jsonb;native_second_unsigned jsonb;native_third jsonb;
 page1 jsonb;page2 jsonb;page3 jsonb;page_empty jsonb;ledger_before text;ledger_after text;
 observed timestamptz:=date_trunc('seconds',clock_timestamp()-interval '2 hours')+interval '0.123456 seconds';
 observed_text text;later_text text;confirmed_text text;passed boolean:=false;schema_name text;blocked_kind text;blocked_packets jsonb:='[]'::jsonb;path_context jsonb;path_command jsonb;
BEGIN
 BEGIN
  INSERT INTO public.tenants(id,name) VALUES(t,'CP365 CareDocumentation synthetic rollback fixture');
  INSERT INTO public.roles(id,key,name) VALUES(r,'cp365_care_documentation_'||r,'Synthetic own documentation role'),(other_role,'cp365_care_documentation_'||other_role,'Synthetic separate documentation role');
  INSERT INTO public.role_permissions(role_id,permission_key) SELECT own.role_id,permission.permission_key FROM unnest(ARRAY[r,other_role]) AS own(role_id) CROSS JOIN unnest(ARRAY['pflege.documentation.view','pflege.documentation.create','pflege.documentation.sign']) AS permission(permission_key);
  INSERT INTO auth.users(id,email,raw_user_meta_data,raw_app_meta_data) VALUES(u,u||'@example.invalid','{}','{}'),(other_actor,other_actor||'@example.invalid','{}','{}');
  UPDATE public.profiles SET tenant_id=t,role_id=r,role_key='pfleger',is_active=true,status='active',display_name='Synthetic documentation author' WHERE id=u;
  UPDATE public.profiles SET tenant_id=t,role_id=other_role,role_key='pfleger',is_active=true,status='active',display_name='Synthetic separate documentation actor' WHERE id=other_actor;
  INSERT INTO auth.sessions(id,user_id,not_after) VALUES(s,u,clock_timestamp()+interval '1 hour'),(other_session,other_actor,clock_timestamp()+interval '1 hour');
  INSERT INTO public.clients(id,tenant_id,first_name,last_name,status,lifecycle_status) VALUES(c,t,'Synthetic','Documentation case','aktiv','aktiv'),(other_client,t,'Synthetic','Other documentation case','aktiv','aktiv');
  INSERT INTO public.client_module_assignments(tenant_id,client_id,module_key,status,is_active) VALUES(t,c,'pflege','active',true),(t,other_client,'pflege','active',true);
  claims:=jsonb_build_object('sub',u,'role','authenticated','session_id',s,'exp',extract(epoch from clock_timestamp()+interval '1 hour')::bigint);
  other_claims:=jsonb_build_object('sub',other_actor,'role','authenticated','session_id',other_session,'exp',extract(epoch from clock_timestamp()+interval '1 hour')::bigint);
  PERFORM set_config('request.jwt.claims',claims::text,true);
  observed_text:=to_char(observed at time zone 'UTC','YYYY-MM-DD"T"HH24:MI:SS.US"Z"');
  later_text:=to_char((observed+interval '1 microsecond') at time zone 'UTC','YYYY-MM-DD"T"HH24:MI:SS.US"Z"');
  confirmed_text:=to_char((observed+interval '1 hour') at time zone 'UTC','YYYY-MM-DD"T"HH24:MI:SS.US"Z"');
  entry:=jsonb_build_object('kind','care_report','title','Synthetic explicitly authored observation','occurredAt',observed_text,'observation','Synthetic actual observation expressly entered for this rollback test','intervention','Synthetic authored account only; no automatically inferred clinical action','result','Synthetic reported status; no treatment or clinical approval asserted','plannedService',null,'refusal',null,'incident',null,'protocol',null,'control',null,'external',null);
  create_packet:=jsonb_build_object('schemaVersion','1','action','create','requestId',create_request,'tenantId',t,'clientId',c,'actorId',u,'expectedHeadId',null,'expectedRevision',0,'entry',entry,'correctionReason','','confirmation',null,'original',null);

  -- Native content signatures remain unavailable without an independently proven bridge.
  -- Only explicitly authored unsigned care_report creation/correction is exercised positively.
  page_empty:=public.web_read_care_documentation_page(p_tenant_id=>t,p_client_id=>c,p_actor_profile_id=>u,p_cursor_occurred_at=>null,p_cursor_id=>null,p_page_size=>1);
  IF jsonb_array_length(page_empty->'rows') IS DISTINCT FROM 0 OR page_empty->'nextCursorOccurredAt' IS DISTINCT FROM 'null'::jsonb OR page_empty->'nextCursorId' IS DISTINCT FROM 'null'::jsonb OR coalesce(page_empty->>'stateFingerprint','')!~'^sha256:[0-9a-f]{64}$' THEN RAISE EXCEPTION 'Empty documentation ledger lacks complete cursor/proof';END IF;
  create_receipt:=public.web_commit_care_documentation_packet(p_packet=>create_packet);first_id:=(create_receipt#>>'{original,id}')::uuid;
  IF create_receipt->'packet' IS DISTINCT FROM create_packet OR create_receipt->>'requestId' IS DISTINCT FROM create_request::text OR first_id IS NULL OR create_receipt#>>'{original,rootId}' IS DISTINCT FROM first_id::text OR create_receipt#>>'{original,headId}' IS DISTINCT FROM first_id::text OR create_receipt#>>'{original,revision}' IS DISTINCT FROM '1' OR jsonb_array_length(create_receipt#>'{original,history}') IS DISTINCT FROM 1 OR create_receipt#>'{original,payload}' IS DISTINCT FROM entry OR create_receipt#>'{original,signature}' IS DISTINCT FROM 'null'::jsonb OR create_receipt#>>'{original,occurredAt}' IS DISTINCT FROM observed_text THEN RAISE EXCEPTION 'Created unsigned native original does not bind the complete authored packet';END IF;
  SELECT to_jsonb(d) INTO native_first FROM public.clinical_documentation_entries d WHERE d.id=first_id;
  IF native_first->>'tenant_id' IS DISTINCT FROM t::text OR native_first->>'client_id' IS DISTINCT FROM c::text OR native_first->>'recorded_by' IS DISTINCT FROM u::text OR native_first->>'title' IS DISTINCT FROM entry->>'title' OR native_first->>'observations' IS DISTINCT FROM entry->>'observation' OR native_first->>'interventions' IS DISTINCT FROM entry->>'intervention' OR native_first->>'result' IS DISTINCT FROM entry->>'result' OR native_first->>'signature_status' IS DISTINCT FROM 'unsigned' THEN RAISE EXCEPTION 'Retained native row invented, omitted or changed authored facts';END IF;
  IF public.web_commit_care_documentation_packet(p_packet=>create_packet) IS DISTINCT FROM create_receipt OR public.web_confirm_care_documentation_packet(p_tenant_id=>t,p_client_id=>c,p_actor_profile_id=>u,p_request_id=>create_request,p_packet=>create_packet) IS DISTINCT FROM create_receipt THEN RAISE EXCEPTION 'Exact own create receipt/replay changed or duplicated';END IF;
  BEGIN PERFORM public.web_commit_care_documentation_packet(p_packet=>jsonb_set(create_packet,'{entry,title}','"Changed request content"'));RAISE EXCEPTION 'Changed request replay accepted';EXCEPTION WHEN check_violation THEN NULL;END;
  BEGIN PERFORM public.web_commit_care_documentation_packet(p_packet=>create_packet||jsonb_build_object('requestId',gen_random_uuid(),'unknown','hidden field'));RAISE EXCEPTION 'Unknown top-level packet field accepted';EXCEPTION WHEN check_violation THEN NULL;END;
  BEGIN PERFORM public.web_commit_care_documentation_packet(p_packet=>create_packet||jsonb_build_object('requestId',gen_random_uuid(),'entry',entry||'{"unknown":"hidden native fact"}'));RAISE EXCEPTION 'Unknown authored entry field accepted';EXCEPTION WHEN check_violation THEN NULL;END;
  BEGIN PERFORM public.web_commit_care_documentation_packet(p_packet=>create_packet||jsonb_build_object('requestId',gen_random_uuid(),'entry',entry-'observation'));RAISE EXCEPTION 'Missing explicit observation accepted';EXCEPTION WHEN check_violation THEN NULL;END;
  BEGIN PERFORM public.web_commit_care_documentation_packet(p_packet=>jsonb_set(create_packet||jsonb_build_object('requestId',gen_random_uuid()),'{entry,occurredAt}',to_jsonb(to_char((clock_timestamp()+interval '1 day') at time zone 'UTC','YYYY-MM-DD"T"HH24:MI:SS.US"Z"'))));RAISE EXCEPTION 'Future actual event accepted';EXCEPTION WHEN check_violation THEN NULL;END;

  correct_packet:=create_packet||jsonb_build_object('action','correct','requestId',correct_request,'expectedHeadId',first_id,'expectedRevision',1,'entry',entry||jsonb_build_object('occurredAt',later_text,'result','Synthetic explicit first append-only correction; original retained'),'correctionReason','Synthetic correction explicitly preserves the earlier authored original','original',create_receipt->'original');
  correct_receipt:=public.web_commit_care_documentation_packet(p_packet=>correct_packet);second_id:=(correct_receipt#>>'{original,id}')::uuid;
  IF second_id IS NULL OR second_id IS NOT DISTINCT FROM first_id OR correct_receipt#>>'{original,rootId}' IS DISTINCT FROM first_id::text OR correct_receipt#>>'{original,revision}' IS DISTINCT FROM '2' OR jsonb_array_length(correct_receipt#>'{original,history}') IS DISTINCT FROM 2 OR correct_receipt#>>'{original,history,1,previousId}' IS DISTINCT FROM first_id::text OR correct_receipt#>'{original,history,0,payload}' IS DISTINCT FROM entry OR correct_receipt#>'{original,payload}' IS DISTINCT FROM correct_packet->'entry' OR correct_receipt#>>'{original,occurredAt}' IS DISTINCT FROM later_text THEN RAISE EXCEPTION 'Append-only correction lost native identity, microseconds or original history';END IF;
  SELECT to_jsonb(d) INTO native_second_unsigned FROM public.clinical_documentation_entries d WHERE d.id=second_id;
  IF native_second_unsigned->>'correction_of_id' IS DISTINCT FROM first_id::text OR native_second_unsigned->>'signature_status' IS DISTINCT FROM 'unsigned' OR (SELECT to_jsonb(d) FROM public.clinical_documentation_entries d WHERE d.id=first_id) IS DISTINCT FROM native_first THEN RAISE EXCEPTION 'Correction overwrote original native content or implied a signature';END IF;
  BEGIN PERFORM public.web_commit_care_documentation_packet(p_packet=>correct_packet||jsonb_build_object('requestId',gen_random_uuid(),'entry',(correct_packet->'entry')||'{"title":"Synthetic stale CAS change"}'));RAISE EXCEPTION 'Stale correction head accepted';EXCEPTION WHEN serialization_failure THEN NULL;END;
  BEGIN PERFORM public.web_commit_care_documentation_packet(p_packet=>correct_packet||jsonb_build_object('requestId',gen_random_uuid(),'expectedHeadId',second_id,'expectedRevision',2,'entry',correct_receipt#>'{original,payload}','original',correct_receipt->'original'));RAISE EXCEPTION 'Unchanged correction accepted';EXCEPTION WHEN check_violation THEN NULL;END;
  BEGIN PERFORM public.web_commit_care_documentation_packet(p_packet=>jsonb_set(correct_packet||jsonb_build_object('requestId',gen_random_uuid(),'expectedHeadId',second_id,'expectedRevision',2,'original',correct_receipt->'original'),'{original,history,0,payload,observation}','"Changed complete historical fact"'));RAISE EXCEPTION 'Altered historical original accepted';EXCEPTION WHEN serialization_failure THEN NULL;END;

  confirm_packet:=create_packet||jsonb_build_object('action','confirm','requestId',confirm_request,'expectedHeadId',second_id,'expectedRevision',2,'entry',null,'original',correct_receipt->'original','confirmation',jsonb_build_object('personId',u,'personName','Synthetic documentation author','role','Synthetic documentation sign role','scope','Synthetic exact content confirmation only','basis','Synthetic content statement, no native qualification or clinical authorization bridge','confirmedAt',confirmed_text,'contentFingerprint',correct_receipt#>'{original,contentFingerprint}'));
  BEGIN PERFORM public.web_commit_care_documentation_packet(p_packet=>confirm_packet);RAISE EXCEPTION 'Unproven native confirmation bridge activated by a synthetic sign role';EXCEPTION WHEN insufficient_privilege THEN NULL;END;
  IF EXISTS(SELECT 1 FROM care_documentation_private.confirmations WHERE tenant_id=t) OR (SELECT signature_status FROM public.clinical_documentation_entries WHERE id=second_id) IS DISTINCT FROM 'unsigned' THEN RAISE EXCEPTION 'Blocked confirmation left a signature or confirmation original';END IF;

  later_packet:=correct_packet||jsonb_build_object('requestId',later_request,'expectedHeadId',second_id,'expectedRevision',2,'entry',(correct_packet->'entry')||jsonb_build_object('occurredAt',to_char((observed+interval '2 microseconds') at time zone 'UTC','YYYY-MM-DD"T"HH24:MI:SS.US"Z"'),'result','Synthetic second explicit correction retains both earlier versions'),'correctionReason','Synthetic second correction with exact current native head','original',correct_receipt->'original');
  later_receipt:=public.web_commit_care_documentation_packet(p_packet=>later_packet);third_id:=(later_receipt#>>'{original,id}')::uuid;
  SELECT to_jsonb(d) INTO native_third FROM public.clinical_documentation_entries d WHERE d.id=third_id;
  IF third_id IS NULL OR later_receipt#>>'{original,revision}' IS DISTINCT FROM '3' OR jsonb_array_length(later_receipt#>'{original,history}') IS DISTINCT FROM 3 OR later_receipt#>'{original,history,0,payload}' IS DISTINCT FROM create_packet->'entry' OR later_receipt#>'{original,history,1,payload}' IS DISTINCT FROM correct_packet->'entry' OR native_third->>'correction_of_id' IS DISTINCT FROM second_id::text THEN RAISE EXCEPTION 'Second correction did not preserve exact complete earlier versions';END IF;
  IF public.web_confirm_care_documentation_packet(p_tenant_id=>t,p_client_id=>c,p_actor_profile_id=>u,p_request_id=>create_request,p_packet=>create_packet) IS DISTINCT FROM create_receipt OR public.web_confirm_care_documentation_packet(p_tenant_id=>t,p_client_id=>c,p_actor_profile_id=>u,p_request_id=>correct_request,p_packet=>correct_packet) IS DISTINCT FROM correct_receipt THEN RAISE EXCEPTION 'Historical own receipt drifted to later history/head';END IF;
  value:=public.web_read_care_documentation_record(p_tenant_id=>t,p_client_id=>c,p_actor_profile_id=>u,p_entry_id=>first_id);
  IF value IS DISTINCT FROM later_receipt->'original' THEN RAISE EXCEPTION 'Current native record did not resolve selected root to latest complete version';END IF;
  UPDATE public.profiles SET display_name='Synthetic author with later display name' WHERE id=u;
  IF public.web_confirm_care_documentation_packet(p_tenant_id=>t,p_client_id=>c,p_actor_profile_id=>u,p_request_id=>create_request,p_packet=>create_packet) IS DISTINCT FROM create_receipt OR public.web_read_care_documentation_record(p_tenant_id=>t,p_client_id=>c,p_actor_profile_id=>u,p_entry_id=>first_id) IS DISTINCT FROM later_receipt->'original' THEN RAISE EXCEPTION 'Current profile display name rewrote immutable historical authorship';END IF;
  UPDATE public.profiles SET display_name='Synthetic documentation author' WHERE id=u;

  -- Separate authored roots share the same exact occurrence time, exercising the UUID tie cursor.
  extra_packet:=create_packet||jsonb_build_object('requestId',gen_random_uuid(),'entry',entry||'{"title":"Synthetic additional current root"}');
  extra_receipt:=public.web_commit_care_documentation_packet(p_packet=>extra_packet);extra_id:=(extra_receipt#>>'{original,id}')::uuid;
  lower_packet:=create_packet||jsonb_build_object('requestId',gen_random_uuid(),'entry',entry||'{"title":"Synthetic second tied current root"}');
  lower_receipt:=public.web_commit_care_documentation_packet(p_packet=>lower_packet);
  page1:=public.web_read_care_documentation_page(p_tenant_id=>t,p_client_id=>c,p_actor_profile_id=>u,p_cursor_occurred_at=>null,p_cursor_id=>null,p_page_size=>1);
  page2:=public.web_read_care_documentation_page(p_tenant_id=>t,p_client_id=>c,p_actor_profile_id=>u,p_cursor_occurred_at=>(page1->>'nextCursorOccurredAt')::timestamptz,p_cursor_id=>(page1->>'nextCursorId')::uuid,p_page_size=>1);
  page3:=public.web_read_care_documentation_page(p_tenant_id=>t,p_client_id=>c,p_actor_profile_id=>u,p_cursor_occurred_at=>(page2->>'nextCursorOccurredAt')::timestamptz,p_cursor_id=>(page2->>'nextCursorId')::uuid,p_page_size=>1);
  page_empty:=public.web_read_care_documentation_page(p_tenant_id=>t,p_client_id=>c,p_actor_profile_id=>u,p_cursor_occurred_at=>(page3->>'nextCursorOccurredAt')::timestamptz,p_cursor_id=>(page3->>'nextCursorId')::uuid,p_page_size=>1);
  IF jsonb_array_length(page1->'rows') IS DISTINCT FROM 1 OR jsonb_array_length(page2->'rows') IS DISTINCT FROM 1 OR jsonb_array_length(page3->'rows') IS DISTINCT FROM 1 OR jsonb_array_length(page_empty->'rows') IS DISTINCT FROM 0 OR page1#>>'{rows,0,id}' IS DISTINCT FROM third_id::text OR page2#>>'{rows,0,id}' IS NULL OR page3#>>'{rows,0,id}' IS NULL OR page2#>>'{rows,0,id}' IS NOT DISTINCT FROM page3#>>'{rows,0,id}' OR page2#>>'{rows,0,occurredAt}' IS DISTINCT FROM observed_text OR page3#>>'{rows,0,occurredAt}' IS DISTINCT FROM observed_text OR (page2#>>'{rows,0,id}')::uuid<=(page3#>>'{rows,0,id}')::uuid OR page_empty->'nextCursorOccurredAt' IS DISTINCT FROM 'null'::jsonb OR page_empty->'nextCursorId' IS DISTINCT FROM 'null'::jsonb THEN RAISE EXCEPTION 'Complete cursor traversal lost a current root, microsecond ordering or equal-time UUID tie';END IF;
  ledger_before:=page1->>'stateFingerprint';
  IF coalesce(ledger_before,'')!~'^sha256:[0-9a-f]{64}$' OR page2->>'stateFingerprint' IS DISTINCT FROM ledger_before OR page3->>'stateFingerprint' IS DISTINCT FROM ledger_before OR page_empty->>'stateFingerprint' IS DISTINCT FROM ledger_before THEN RAISE EXCEPTION 'Current/older/empty documentation pages do not attest one complete ledger';END IF;
  BEGIN PERFORM public.web_read_care_documentation_page(p_tenant_id=>t,p_client_id=>c,p_actor_profile_id=>u,p_cursor_occurred_at=>observed,p_cursor_id=>null,p_page_size=>1);RAISE EXCEPTION 'Partial cursor pair accepted';EXCEPTION WHEN invalid_parameter_value THEN NULL;END;
  BEGIN PERFORM public.web_read_care_documentation_page(p_tenant_id=>t,p_client_id=>c,p_actor_profile_id=>u,p_cursor_occurred_at=>null,p_cursor_id=>null,p_page_size=>null);RAISE EXCEPTION 'Null page size accepted';EXCEPTION WHEN invalid_parameter_value THEN NULL;END;
  BEGIN PERFORM public.web_read_care_documentation_page(p_tenant_id=>t,p_client_id=>c,p_actor_profile_id=>u,p_cursor_occurred_at=>null,p_cursor_id=>null,p_page_size=>0);RAISE EXCEPTION 'Zero page size accepted';EXCEPTION WHEN invalid_parameter_value THEN NULL;END;
  BEGIN PERFORM public.web_read_care_documentation_page(p_tenant_id=>t,p_client_id=>c,p_actor_profile_id=>u,p_cursor_occurred_at=>observed,p_cursor_id=>first_id,p_page_size=>1);RAISE EXCEPTION 'Superseded native version accepted as current cursor';EXCEPTION WHEN serialization_failure THEN NULL;END;
  foreign_packet:=create_packet||jsonb_build_object('requestId',gen_random_uuid(),'clientId',other_client,'entry',entry||'{"title":"Synthetic foreign-client cursor original"}');
  foreign_receipt:=public.web_commit_care_documentation_packet(p_packet=>foreign_packet);
  BEGIN PERFORM public.web_read_care_documentation_page(p_tenant_id=>t,p_client_id=>c,p_actor_profile_id=>u,p_cursor_occurred_at=>observed,p_cursor_id=>(foreign_receipt#>>'{original,id}')::uuid,p_page_size=>1);RAISE EXCEPTION 'Other client current head accepted as cursor';EXCEPTION WHEN serialization_failure THEN NULL;END;
  value:=public.web_read_care_documentation_page(p_tenant_id=>t,p_client_id=>c,p_actor_profile_id=>u,p_cursor_occurred_at=>null,p_cursor_id=>null,p_page_size=>1);
  IF value->>'stateFingerprint' IS DISTINCT FROM ledger_before THEN RAISE EXCEPTION 'Other-client write contaminated the own documentation ledger';END IF;
  older_packet:=create_packet||jsonb_build_object('action','correct','requestId',gen_random_uuid(),'expectedHeadId',page3#>'{rows,0,headId}','expectedRevision',1,'entry',(page3#>'{rows,0,payload}')||'{"result":"Synthetic older-page correction with unchanged first root"}','correctionReason','Synthetic targeted older-page ledger mutation','original',page3#>'{rows,0}');
  older_receipt:=public.web_commit_care_documentation_packet(p_packet=>older_packet);
  value:=public.web_read_care_documentation_page(p_tenant_id=>t,p_client_id=>c,p_actor_profile_id=>u,p_cursor_occurred_at=>null,p_cursor_id=>null,p_page_size=>1);ledger_after:=value->>'stateFingerprint';
  IF value->'rows' IS DISTINCT FROM page1->'rows' OR ledger_after IS NULL OR ledger_after IS NOT DISTINCT FROM ledger_before THEN RAISE EXCEPTION 'Older page changed without changing complete ledger proof, or unexpectedly rewrote first root';END IF;

  -- Each gate is evaluated using the actual own role/session, even for an exact replay.
  BEGIN DELETE FROM public.role_permissions WHERE role_id=r AND permission_key='pflege.documentation.view';PERFORM public.web_read_care_documentation_page(p_tenant_id=>t,p_client_id=>c,p_actor_profile_id=>u,p_cursor_occurred_at=>null,p_cursor_id=>null,p_page_size=>1);RAISE EXCEPTION 'Other actor role lent documentation view rights';EXCEPTION WHEN insufficient_privilege THEN NULL;END;
  BEGIN INSERT INTO public.role_permission_sets(tenant_id,role_key,permission_key) VALUES(t,'cp365_care_documentation_'||r,'pflege.documentation.view');PERFORM public.web_commit_care_documentation_packet(p_packet=>create_packet);RAISE EXCEPTION 'Tenant role override borrowed global create permission';EXCEPTION WHEN insufficient_privilege THEN NULL;END;
  BEGIN INSERT INTO public.role_permission_sets(tenant_id,role_key,permission_key) VALUES(t,'cp365_care_documentation_'||r,'pflege.documentation.create');PERFORM public.web_read_care_documentation_record(p_tenant_id=>t,p_client_id=>c,p_actor_profile_id=>u,p_entry_id=>first_id);RAISE EXCEPTION 'Tenant role override borrowed global view permission';EXCEPTION WHEN insufficient_privilege THEN NULL;END;
  BEGIN DELETE FROM public.role_permissions WHERE role_id=r AND permission_key='pflege.documentation.create';PERFORM public.web_commit_care_documentation_packet(p_packet=>create_packet);RAISE EXCEPTION 'Exact replay bypassed current own create permission';EXCEPTION WHEN insufficient_privilege THEN NULL;END;
  BEGIN DELETE FROM public.role_permissions WHERE role_id=r AND permission_key='pflege.documentation.create';IF public.web_confirm_care_documentation_packet(p_tenant_id=>t,p_client_id=>c,p_actor_profile_id=>u,p_request_id=>create_request,p_packet=>create_packet) IS DISTINCT FROM create_receipt THEN RAISE EXCEPTION 'Read-only own historical receipt changed after loss of create permission';END IF;RAISE EXCEPTION USING ERRCODE='Z0002';EXCEPTION WHEN SQLSTATE 'Z0002' THEN NULL;END;
  BEGIN PERFORM set_config('request.jwt.claims',(claims||jsonb_build_object('session_id',other_session))::text,true);PERFORM public.web_read_care_documentation_record(p_tenant_id=>t,p_client_id=>c,p_actor_profile_id=>u,p_entry_id=>first_id);RAISE EXCEPTION 'Another actual account session was borrowed';EXCEPTION WHEN insufficient_privilege THEN NULL;END;
  BEGIN UPDATE auth.sessions SET not_after=clock_timestamp()-interval '1 minute' WHERE id=s;PERFORM public.web_read_care_documentation_record(p_tenant_id=>t,p_client_id=>c,p_actor_profile_id=>u,p_entry_id=>first_id);RAISE EXCEPTION 'Expired actual session read documentation';EXCEPTION WHEN insufficient_privilege THEN NULL;END;
  BEGIN PERFORM set_config('request.jwt.claims',(claims||jsonb_build_object('exp',extract(epoch from clock_timestamp()-interval '1 minute')::bigint))::text,true);PERFORM public.web_read_care_documentation_record(p_tenant_id=>t,p_client_id=>c,p_actor_profile_id=>u,p_entry_id=>first_id);RAISE EXCEPTION 'Expired JWT read documentation';EXCEPTION WHEN insufficient_privilege THEN NULL;END;
  BEGIN UPDATE public.profiles SET is_active=false WHERE id=u;PERFORM public.web_read_care_documentation_record(p_tenant_id=>t,p_client_id=>c,p_actor_profile_id=>u,p_entry_id=>first_id);RAISE EXCEPTION 'Inactive own profile read documentation';EXCEPTION WHEN insufficient_privilege THEN NULL;END;
  BEGIN UPDATE public.clients SET lifecycle_status='archiviert' WHERE id=c;PERFORM public.web_read_care_documentation_record(p_tenant_id=>t,p_client_id=>c,p_actor_profile_id=>u,p_entry_id=>first_id);RAISE EXCEPTION 'Archived care lifecycle read documentation';EXCEPTION WHEN insufficient_privilege THEN NULL;END;
  BEGIN UPDATE public.clients SET archived_at=clock_timestamp() WHERE id=c;PERFORM public.web_read_care_documentation_record(p_tenant_id=>t,p_client_id=>c,p_actor_profile_id=>u,p_entry_id=>first_id);RAISE EXCEPTION 'Archived native case metadata read documentation';EXCEPTION WHEN insufficient_privilege THEN NULL;END;
  BEGIN UPDATE public.clients SET deleted_at=clock_timestamp() WHERE id=c;PERFORM public.web_confirm_care_documentation_packet(p_tenant_id=>t,p_client_id=>c,p_actor_profile_id=>u,p_request_id=>create_request,p_packet=>create_packet);RAISE EXCEPTION 'Deleted care case recovered own receipt';EXCEPTION WHEN insufficient_privilege THEN NULL;END;
  BEGIN UPDATE public.client_module_assignments SET is_active=false WHERE tenant_id=t AND client_id=c AND module_key='pflege';PERFORM public.web_read_care_documentation_record(p_tenant_id=>t,p_client_id=>c,p_actor_profile_id=>u,p_entry_id=>first_id);RAISE EXCEPTION 'Missing active Pflege assignment read documentation';EXCEPTION WHEN insufficient_privilege THEN NULL;END;
  BEGIN PERFORM public.web_read_care_documentation_record(p_tenant_id=>gen_random_uuid(),p_client_id=>c,p_actor_profile_id=>u,p_entry_id=>first_id);RAISE EXCEPTION 'Foreign tenant parameter read documentation';EXCEPTION WHEN insufficient_privilege THEN NULL;END;
  BEGIN PERFORM public.web_read_care_documentation_record(p_tenant_id=>t,p_client_id=>c,p_actor_profile_id=>other_actor,p_entry_id=>first_id);RAISE EXCEPTION 'Foreign actor parameter read documentation';EXCEPTION WHEN insufficient_privilege THEN NULL;END;
  BEGIN PERFORM public.web_read_care_documentation_record(p_tenant_id=>t,p_client_id=>other_client,p_actor_profile_id=>u,p_entry_id=>first_id);RAISE EXCEPTION 'Other client read an unrelated document original';EXCEPTION WHEN SQLSTATE 'P0E01' THEN NULL;END;
  BEGIN PERFORM public.web_confirm_care_documentation_packet(p_tenant_id=>t,p_client_id=>other_client,p_actor_profile_id=>u,p_request_id=>create_request,p_packet=>create_packet);RAISE EXCEPTION 'Other client recovered own receipt';EXCEPTION WHEN SQLSTATE 'P0E02' THEN NULL;END;
  BEGIN PERFORM public.web_confirm_care_documentation_packet(p_tenant_id=>t,p_client_id=>c,p_actor_profile_id=>u,p_request_id=>gen_random_uuid(),p_packet=>create_packet);RAISE EXCEPTION 'Unknown request recovered an unrelated receipt';EXCEPTION WHEN SQLSTATE 'P0E02' THEN NULL;END;
  BEGIN PERFORM public.web_confirm_care_documentation_packet(p_tenant_id=>t,p_client_id=>c,p_actor_profile_id=>u,p_request_id=>create_request,p_packet=>jsonb_set(create_packet,'{entry,title}','"Changed captured own request"'));RAISE EXCEPTION 'Changed complete request recovered an own receipt';EXCEPTION WHEN SQLSTATE 'P0E02' THEN NULL;END;
  BEGIN PERFORM set_config('request.jwt.claims',other_claims::text,true);PERFORM public.web_confirm_care_documentation_packet(p_tenant_id=>t,p_client_id=>c,p_actor_profile_id=>other_actor,p_request_id=>create_request,p_packet=>create_packet);RAISE EXCEPTION 'Different authenticated author recovered another actor receipt';EXCEPTION WHEN SQLSTATE 'P0E02' THEN NULL;END;

  -- An actual second account resolving to the same internal profile cannot adopt the old account's request.
  BEGIN
   INSERT INTO auth.users(id,email,raw_user_meta_data,raw_app_meta_data) VALUES(relinked_auth,relinked_auth||'@example.invalid','{}','{}');
   DELETE FROM public.profiles WHERE id=relinked_auth;
   UPDATE public.profiles SET auth_user_id=relinked_auth WHERE id=u;
   INSERT INTO auth.sessions(id,user_id,not_after) VALUES(relinked_session,relinked_auth,clock_timestamp()+interval '1 hour');
   PERFORM set_config('request.jwt.claims',jsonb_build_object('sub',relinked_auth,'role','authenticated','session_id',relinked_session,'exp',extract(epoch from clock_timestamp()+interval '1 hour')::bigint)::text,true);
   IF public.resolve_current_profile_id() IS DISTINCT FROM u THEN RAISE EXCEPTION 'Synthetic account relink did not resolve to the exact original internal profile';END IF;
   PERFORM care_documentation_private.require_scope(t,c,u,false);
   BEGIN PERFORM public.web_commit_care_documentation_packet(p_packet=>create_packet);RAISE EXCEPTION 'Different actual account replayed the same internal profile request';EXCEPTION WHEN check_violation THEN NULL;END;
   BEGIN PERFORM public.web_confirm_care_documentation_packet(p_tenant_id=>t,p_client_id=>c,p_actor_profile_id=>u,p_request_id=>create_request,p_packet=>create_packet);RAISE EXCEPTION 'Different actual account confirmed the same internal profile receipt';EXCEPTION WHEN SQLSTATE 'P0E02' THEN NULL;END;
   relink_checked:=true;RAISE EXCEPTION USING ERRCODE='Z0002';
  EXCEPTION WHEN SQLSTATE 'Z0002' THEN NULL;END;
  IF relink_checked IS DISTINCT FROM true OR public.resolve_current_profile_id() IS DISTINCT FROM u OR auth.uid() IS DISTINCT FROM u THEN RAISE EXCEPTION 'Synthetic account relink proof or nested authority cleanup failed';END IF;

  -- New captured rows are immutable; an unrelated historical/native row is not rewritten or locked by this package.
  BEGIN UPDATE public.clinical_documentation_entries SET observations='Changed captured native content' WHERE id=first_id;RAISE EXCEPTION 'Captured native content mutable';EXCEPTION WHEN insufficient_privilege THEN NULL;END;
  BEGIN DELETE FROM public.clinical_documentation_entries WHERE id=first_id;RAISE EXCEPTION 'Captured native original deletable';EXCEPTION WHEN insufficient_privilege THEN NULL;END;
  BEGIN UPDATE care_documentation_private.versions SET payload=jsonb_set(payload,'{observation}','"Changed retained version"') WHERE id=second_id;RAISE EXCEPTION 'Retained authored version mutable';EXCEPTION WHEN insufficient_privilege THEN NULL;END;
  BEGIN DELETE FROM care_documentation_private.versions WHERE id=second_id;RAISE EXCEPTION 'Retained authored version deletable';EXCEPTION WHEN insufficient_privilege THEN NULL;END;
  BEGIN UPDATE care_documentation_private.requests SET packet_original=jsonb_set(packet_original,'{entry,title}','"Changed own request original"') WHERE request_id=create_request;RAISE EXCEPTION 'Own stored request mutable';EXCEPTION WHEN insufficient_privilege THEN NULL;END;
  BEGIN DELETE FROM care_documentation_private.requests WHERE request_id=create_request;RAISE EXCEPTION 'Own stored request deletable';EXCEPTION WHEN insufficient_privilege THEN NULL;END;
  INSERT INTO public.clinical_documentation_entries(id,tenant_id,client_id,entry_type,title,content,observations,interventions,result,deviation,escalation,recorded_at,recorded_by,recorded_by_name,signature_status,correction_of_id,correction_reason) VALUES(legacy_id,t,c,'care_report','Synthetic unrelated historical capture','Synthetic legacy content','Synthetic legacy observation','','','','',observed,u,'Synthetic documentation author','unsigned',null,'');
  UPDATE public.clinical_documentation_entries SET observations='Synthetic unchanged legacy writer behavior' WHERE id=legacy_id;
  DELETE FROM public.clinical_documentation_entries WHERE id=legacy_id;
  IF EXISTS(SELECT 1 FROM public.clinical_documentation_entries WHERE id=legacy_id) OR (SELECT to_jsonb(d) FROM public.clinical_documentation_entries d WHERE d.id=first_id) IS DISTINCT FROM native_first THEN RAISE EXCEPTION 'Legacy behavior was widened or protected new original was changed';END IF;

  IF (SELECT count(DISTINCT p.proname) FROM pg_proc p JOIN pg_namespace n ON n.oid=p.pronamespace WHERE n.nspname='public' AND p.proname IN('web_read_care_documentation_page','web_read_care_documentation_record','web_commit_care_documentation_packet','web_confirm_care_documentation_packet','web_care_documentation_path_workspace_context','web_commit_care_documentation_path_event','web_confirm_care_documentation_path_event')) IS DISTINCT FROM 7 THEN RAISE EXCEPTION 'Expected four core and three legacy path signatures missing';END IF;
  IF EXISTS(SELECT 1 FROM pg_proc p JOIN pg_namespace n ON n.oid=p.pronamespace WHERE n.nspname='public' AND p.proname IN('web_read_care_documentation_page','web_read_care_documentation_record','web_commit_care_documentation_packet','web_confirm_care_documentation_packet','web_care_documentation_path_workspace_context','web_commit_care_documentation_path_event','web_confirm_care_documentation_path_event') AND (has_function_privilege('anon',p.oid,'EXECUTE') OR has_function_privilege('authenticated',p.oid,'EXECUTE') OR has_function_privilege('service_role',p.oid,'EXECUTE'))) THEN RAISE EXCEPTION 'CareDocumentation core/path API quarantine missing';END IF;
  FOREACH schema_name IN ARRAY ARRAY['care_documentation_private','care_documentation_path_private'] LOOP
   IF EXISTS(SELECT 1 FROM pg_proc p JOIN pg_namespace n ON n.oid=p.pronamespace WHERE n.nspname=schema_name AND(has_function_privilege('anon',p.oid,'EXECUTE') OR has_function_privilege('authenticated',p.oid,'EXECUTE') OR has_function_privilege('service_role',p.oid,'EXECUTE'))) THEN RAISE EXCEPTION 'Private documentation function execution exposed';END IF;
   IF EXISTS(SELECT 1 FROM pg_class rel JOIN pg_namespace n ON n.oid=rel.relnamespace WHERE n.nspname=schema_name AND rel.relkind IN('r','p') AND (rel.relrowsecurity IS DISTINCT FROM true OR has_table_privilege('anon',rel.oid,'SELECT,INSERT,UPDATE,DELETE') OR has_table_privilege('authenticated',rel.oid,'SELECT,INSERT,UPDATE,DELETE') OR has_table_privilege('service_role',rel.oid,'SELECT,INSERT,UPDATE,DELETE'))) THEN RAISE EXCEPTION 'Private documentation table RLS or privilege quarantine missing';END IF;
  END LOOP;
  FOREACH value IN ARRAY ARRAY[create_receipt,correct_receipt,later_receipt,extra_receipt,lower_receipt,older_receipt,foreign_receipt] LOOP
   SELECT to_jsonb(v) INTO bad FROM care_documentation_private.versions v WHERE v.id=(value#>>'{original,id}')::uuid;
   IF bad IS NULL OR bad->>'request_id' IS DISTINCT FROM value#>>'{packet,requestId}' OR bad->>'auth_user_id' IS DISTINCT FROM u::text OR bad->>'actor_profile_id' IS DISTINCT FROM u::text OR value#>>'{original,tenantId}' IS DISTINCT FROM value#>>'{packet,tenantId}' OR value#>>'{original,clientId}' IS DISTINCT FROM value#>>'{packet,clientId}' OR value#>>'{original,recordedBy}' IS DISTINCT FROM u::text OR value#>>'{original,recordedByName}' IS DISTINCT FROM bad->>'actor_name_snapshot' OR value#>>'{original,kind}' IS DISTINCT FROM 'care_report' OR value#>'{original,signature}' IS DISTINCT FROM 'null'::jsonb OR value#>'{original,payload}' IS DISTINCT FROM value#>'{packet,entry}' OR value#>>'{original,occurredAt}' IS DISTINCT FROM value#>>'{packet,entry,occurredAt}' OR jsonb_array_length(value#>'{original,history}') IS DISTINCT FROM (bad->>'revision')::integer OR (value#>>'{original,recordedAt}')::timestamptz IS DISTINCT FROM (bad->>'created_at')::timestamptz OR NOT EXISTS(SELECT 1 FROM care_documentation_private.requests request_row WHERE request_row.request_id=(value#>>'{packet,requestId}')::uuid AND request_row.version_id=(value#>>'{original,id}')::uuid AND request_row.auth_user_id=u AND request_row.packet_original=value->'packet' AND request_row.original=value->'original') THEN RAISE EXCEPTION 'A retained own receipt changed scope, account, native version, author snapshot, microseconds or complete original';END IF;
  END LOOP;

  path_context:=public.web_care_documentation_path_workspace_context(p_tenant_id=>t,p_client_id=>c,p_actor_id=>u);
  IF path_context->>'version' IS DISTINCT FROM '2026-10-16.5' OR path_context->>'tenantId' IS DISTINCT FROM t::text OR path_context->>'clientId' IS DISTINCT FROM c::text OR path_context->>'actorId' IS DISTINCT FROM u::text OR (path_context#>>'{sources,count}')::integer IS DISTINCT FROM jsonb_array_length(path_context#>'{sources,rows}') OR path_context#>>'{sources,stateFingerprint}' IS DISTINCT FROM ledger_after OR path_context#>>'{history,count}' IS DISTINCT FROM '0' OR path_context#>'{history,headId}' IS DISTINCT FROM 'null'::jsonb OR jsonb_array_length(path_context#>'{history,events}') IS DISTINCT FROM 0 THEN RAISE EXCEPTION 'Quarantined documentation path context lost exact scope, ledger or empty retained history';END IF;
  SELECT source INTO value FROM jsonb_array_elements(path_context#>'{sources,rows}') AS source WHERE source->>'kind'='care_documentation' AND source->>'id'=first_id::text;
  IF value->'snapshot' IS DISTINCT FROM native_first THEN RAISE EXCEPTION 'Path context replaced the exact native documentation original';END IF;
  path_command:=jsonb_build_object('version','2026-10-16.5','requestId',gen_random_uuid(),'eventId',gen_random_uuid(),'tenantId',t,'clientId',c,'actorId',u,'expectedHeadId',null,'kind','control_order','occurredAt',observed_text,'note','Synthetic missing native control bridge remains blocked','payload',jsonb_build_object('basis',value,'cause','Synthetic explicitly proposed control reason','frequency','Synthetic requested frequency','responsible','Synthetic named responsible person','dueAt',confirmed_text));
  BEGIN PERFORM public.web_commit_care_documentation_path_event(p_command=>path_command);RAISE EXCEPTION 'Quarantined clinical documentation path accepted a fresh control write';EXCEPTION WHEN insufficient_privilege THEN NULL;END;
  BEGIN PERFORM public.web_confirm_care_documentation_path_event(p_tenant_id=>t,p_client_id=>c,p_actor_id=>u,p_request_id=>(path_command->>'requestId')::uuid,p_command=>path_command);RAISE EXCEPTION 'Unproven original-account legacy path receipt was accepted';EXCEPTION WHEN insufficient_privilege THEN NULL;END;
  IF EXISTS(SELECT 1 FROM care_documentation_path_private.roots WHERE tenant_id=t) OR EXISTS(SELECT 1 FROM care_documentation_path_private.events WHERE tenant_id=t) THEN RAISE EXCEPTION 'Blocked native path left a root or event';END IF;

  -- Fully shaped unsupported kinds cannot turn invented plan/visit/template/source IDs into native care facts.
  FOREACH blocked_kind IN ARRAY ARRAY['planned_service','refusal','incident','structured_protocol','control','external'] LOOP
   value:=entry||jsonb_build_object('kind',blocked_kind);
   IF blocked_kind='planned_service' THEN value:=value||jsonb_build_object('plannedService',jsonb_build_object('planVersionId',gen_random_uuid(),'visitId',gen_random_uuid(),'outcome','not_performed','reason','Synthetic absent native plan and visit binding','reaction','Synthetic request remains blocked; no performance asserted'));
   ELSIF blocked_kind='refusal' THEN value:=value||jsonb_build_object('result','Synthetic offer refused; no own performance','refusal',jsonb_build_object('measure','Synthetic offered measure','statedReason','Synthetic stated refusal','consultation','Synthetic authored consultation statement','followUp','Synthetic explicitly authored next step'));
   ELSIF blocked_kind='incident' THEN value:=value||jsonb_build_object('incident',jsonb_build_object('incidentType','Synthetic reported incident','people','Synthetic participants only','measures','Synthetic authored reported response','forwardedTo','Synthetic responsible service','closureState','open','closureEvidence',''));
   ELSIF blocked_kind='structured_protocol' THEN value:=value||jsonb_build_object('protocol',jsonb_build_object('protocolType','Synthetic absent native protocol','fields',jsonb_build_array(jsonb_build_object('key','synthetic','label','Synthetic explicit field','value','Synthetic authored statement','unit','')),'specialistVersion','Synthetic absent native template version'));
   ELSIF blocked_kind='control' THEN value:=value||jsonb_build_object('control',jsonb_build_object('cause','Synthetic authored control reason','frequency','Synthetic explicitly requested frequency','responsible','Synthetic responsible person','dueAt',confirmed_text,'resultState','pending','result','','nonPerformanceReason',''));
   ELSIF blocked_kind='external' THEN value:=value||jsonb_build_object('result','Synthetic source statement only; no own performance','external',jsonb_build_object('source','Synthetic absent external original','author','Synthetic external author','receivedAt',confirmed_text,'eventAt',observed_text,'review','Synthetic explicit source review statement'));
   END IF;
   packet:=create_packet||jsonb_build_object('requestId',gen_random_uuid(),'entry',value);
   BEGIN PERFORM public.web_commit_care_documentation_packet(p_packet=>packet);RAISE EXCEPTION 'Missing native clinical bridge accepted for %',blocked_kind;EXCEPTION WHEN insufficient_privilege THEN blocked_packets:=blocked_packets||jsonb_build_array(jsonb_build_object('kind',blocked_kind,'packet',packet,'sqlState','42501'));END;
  END LOOP;
  IF jsonb_array_length(blocked_packets) IS DISTINCT FROM 6 OR (SELECT count(*) FROM care_documentation_private.versions WHERE tenant_id=t) IS DISTINCT FROM 7 OR (SELECT count(*) FROM care_documentation_private.requests WHERE tenant_id=t) IS DISTINCT FROM 7 OR (SELECT count(*) FROM public.clinical_documentation_entries WHERE tenant_id=t) IS DISTINCT FROM 7 OR EXISTS(SELECT 1 FROM care_documentation_private.confirmations WHERE tenant_id=t) THEN RAISE EXCEPTION 'Blocked clinical bridges left a native version, confirmation or request';END IF;

  passed:=true;RAISE EXCEPTION USING ERRCODE='Z0001';
 EXCEPTION WHEN SQLSTATE 'Z0001' THEN NULL;END;
 IF passed IS DISTINCT FROM true OR EXISTS(SELECT 1 FROM public.tenants WHERE id=t) OR EXISTS(SELECT 1 FROM auth.users WHERE id IN(u,other_actor,relinked_auth)) OR EXISTS(SELECT 1 FROM public.profiles WHERE id IN(u,other_actor,relinked_auth)) OR EXISTS(SELECT 1 FROM auth.sessions WHERE id IN(s,other_session,relinked_session)) OR EXISTS(SELECT 1 FROM public.roles WHERE id IN(r,other_role)) OR EXISTS(SELECT 1 FROM public.role_permissions WHERE role_id IN(r,other_role)) OR EXISTS(SELECT 1 FROM public.role_permission_sets WHERE tenant_id=t) OR EXISTS(SELECT 1 FROM public.clients WHERE id IN(c,other_client)) OR EXISTS(SELECT 1 FROM public.client_module_assignments WHERE tenant_id=t) OR EXISTS(SELECT 1 FROM public.clinical_documentation_entries WHERE tenant_id=t) OR EXISTS(SELECT 1 FROM care_documentation_private.versions WHERE tenant_id=t) OR EXISTS(SELECT 1 FROM care_documentation_private.confirmations WHERE tenant_id=t) OR EXISTS(SELECT 1 FROM care_documentation_private.requests WHERE tenant_id=t) OR EXISTS(SELECT 1 FROM care_documentation_path_private.roots WHERE tenant_id=t) OR EXISTS(SELECT 1 FROM care_documentation_path_private.events WHERE tenant_id=t) THEN RAISE EXCEPTION 'CareDocumentation fixture or full synthetic cleanup failed';END IF;
 PERFORM set_config('cp365.care_documentation_test_evidence',jsonb_build_object('schemaVersion',1,'cleanupConfirmed',true,'sameProfileDifferentAuthReplayDenied',relink_checked,'blockedNativeBridgeCases',blocked_packets,'pathContext',path_context,'blockedPathCommand',path_command,'expected',jsonb_build_object('tenantId',t,'clientId',c,'actorId',u,'createRequestId',create_request,'correctRequestId',correct_request,'blockedConfirmationRequestId',confirm_request,'laterRequestId',later_request,'firstVersionId',first_id,'secondVersionId',second_id,'thirdVersionId',third_id),'createPacket',create_packet,'createReceipt',create_receipt,'correctPacket',correct_packet,'correctReceipt',correct_receipt,'blockedConfirmationPacket',confirm_packet,'laterPacket',later_packet,'laterReceipt',later_receipt,'nativeFirst',native_first,'nativeSecondUnsigned',native_second_unsigned,'nativeThird',native_third,'extraPacket',extra_packet,'extraReceipt',extra_receipt,'lowerPacket',lower_packet,'lowerReceipt',lower_receipt,'olderPacket',older_packet,'olderReceipt',older_receipt,'firstPage',page1,'secondPage',page2,'thirdPage',page3,'emptyPage',page_empty)::text,true);
END $test$;
SELECT current_setting('cp365.care_documentation_test_evidence',true)::jsonb AS evidence;
ROLLBACK;
